+++ avro/io.php 2011-10-17 12:41:47.414485600 -0500
@@ -201,7 +201,9 @@
   public function read($len)
   {
     $this->check_closed();
-    $read = array_slice($this->buffer, $this->current_index, $len);
+    $read=array();
+    for($i=$this->current_index; $i<($this->current_index+$len); $i++)
+      $read []=$this->buffer[$i];
     if (count($read) < $len)
